using System.Reflection;using System.Text.Json;
namespace RisingLands;
public static class GreenAssaultTests {
 static object? Call(Simulation s,string name,params object[] args)=>typeof(Simulation).GetMethod(name,BindingFlags.Instance|BindingFlags.NonPublic)!.Invoke(s,args);
 public static void Run(string root,string output){int count=0;void Check(bool ok,string label){if(!ok)throw new Exception(label);count++;Console.WriteLine("PASS "+label);}
 var s=BaseDefenseTests.Load(root,5,12);var p=s.PolicyFor(3);Check(p.MinimumWave==5&&p.MaximumWave==8&&p.ArmyTarget==13,"early green assault has larger minimum and army budget");foreach(int o in new[]{1,2})Check(s.PolicyFor(o)==OpponentPolicyProfile.ForMission(5),"other clan policy unchanged "+o);Check(p.ReserveMinutes==s.PolicyFor(1).ReserveMinutes&&p.StableSeconds==s.PolicyFor(1).StableSeconds&&p.Guards==s.PolicyFor(1).Guards,"green still preserves survival and stabilization");
 var candidates=s.World.Units.Where(a=>a.Owner==3&&a.Type==0&&VisualCatalog.Visible(a)).Take(10).ToArray();candidates[0].Type=2;candidates[1].Type=8;var wave=(Actor[])Call(s,"GreenAssaultWave",(object)candidates)!;Check(wave.Length==8&&wave.Any(a=>a.Type==2)&&wave.Any(a=>a.Type==8)&&wave.Any(a=>a.Type==0),"assault combines support range and frontline");Check(wave.Select(a=>a.Slot).Distinct().Count()==wave.Length,"selection never duplicates units");Check(!(bool)Call(s,"GreenAssaultReady",(object)wave.Take(4).ToArray())!,"green rejects small harassment group");Check((bool)Call(s,"GreenAssaultReady",(object)wave)!,"healthy combined group can attack without advanced locked troop requirement");foreach(var a in wave)a.Health=1;Check(!(bool)Call(s,"GreenAssaultReady",(object)wave)!,"crippled army does not count as destructive assault");
 var opening=BaseDefenseTests.Load(root,5,12);Call(opening,"PrepareOpponentWave",3);Check(opening.Opponent.Sorties.Count==0,"ten-minute economic opening still blocks assault");typeof(Simulation).GetProperty("Tick")!.SetValue(opening,18000L);opening.Campaign.Alliances[3]=true;Call(opening,"PrepareOpponentWave",3);Check(opening.Opponent.Sorties.Count==0,"green never attacks allied player");opening.Campaign.Alliances[3]=false;Call(opening,"PrepareOpponentWave",3);Check(opening.Opponent.Sorties.Count==0,"unsettled economy cannot launch assault");
 var residents=opening.World.Units.Where(a=>a.Owner==3&&a.Type==9&&a.Health>0).Take(3).ToArray();int index=0;foreach(int type in new[]{2,3,4}){var b=opening.World.Buildings.FirstOrDefault(b=>b.Owner==3&&b.Type==type);if(b==null){b=new Building(6200+type,type,3,opening.World.Buildings.First(b=>b.Owner==3&&b.Type==2).Cell-12+type*256);opening.World.Buildings.Add(b);}int id=residents[index++].Slot;foreach(var list in opening.World.BuildingResidents.Values)list.Remove(id);opening.World.BuildingResidents[b.Slot]=new(){id};opening.World.Units.First(a=>a.Slot==id).LegacyState=14;}
 opening.World.Resources[3]=2000;var economy=opening.EconomyFor(3);economy.Initialized=true;economy.StableTicks=36000;economy.Income=20;economy.Maintenance=1;economy.KnownFood=100;economy.Reserve=20;Call(opening,"UpdateBaseDefense",3);Check(opening.EconomyReady(3),"assault fixture establishes genuine operated basic services");Call(opening,"PrepareOpponentWave",3);Check(opening.Opponent.Sorties.Count==8,"prepared green actually deploys larger assault");Check(opening.BaseDefenseFor(3).Guards.Keys.All(id=>!opening.Opponent.Sorties.ContainsKey(id)),"destructive assault preserves all assigned defenders");Check(opening.Opponent.Sorties.Values.All(t=>t==opening.Tick+5400),"green assault has longer operational window");
 var attacker=opening.World.Units.First(a=>opening.Opponent.Sorties.ContainsKey(a.Slot));int cell=attacker.Y/1024*256+attacker.X/1024;var targetDepot=new Building(6300,3,0,cell-6);var targetBarracks=new Building(6301,1,0,cell-5);opening.World.Buildings.AddRange(new[]{targetDepot,targetBarracks});var vision=new byte[65536];vision[targetDepot.Cell]=vision[targetBarracks.Cell]=1;Check(((Building?)Call(opening,"GreenSiegeTarget",attacker,vision))?.Slot==targetBarracks.Slot,"green prioritizes nearby military producer for siege");vision[targetBarracks.Cell]=0;Check(((Building?)Call(opening,"GreenSiegeTarget",attacker,vision))?.Slot==targetDepot.Slot,"green never chooses unseen building");
 var natural=BaseDefenseTests.Load(root);for(int i=0;i<300;i++)natural.Step();string json=natural.Serialize();var copy=BaseDefenseTests.Load(root);copy.Restore(json);Check(copy.Serialize()==json,"green policy compatible with existing save state");for(int i=0;i<300;i++){natural.Step();copy.Step();}Check(copy.Serialize()==natural.Serialize(),"green continuation deterministic");var noEnemies=BaseDefenseTests.Load(root,6);for(int i=0;i<60;i++)noEnemies.Step();Check(!noEnemies.OpponentEnabled&&noEnemies.Opponent.Sorties.Count==0,"mission6 remains exploration without opponents");
 File.WriteAllText(output,JsonSerializer.Serialize(new{Checks=count,Passed=true,Limit="Controlled army fixtures and natural opening; no manual balance approval"},new JsonSerializerOptions{WriteIndented=true}));
 }
}
